INSERT INTO `riesgos` (`id`, `local_id`, `area_id`, `ejercicio_id`, `objetivo`, `riesgo`, `factores`, `probabilidad`, `impacto`, `probabilidad_inicial`, `impacto_inicial`, `status`, `last_observation`, `created_at`, `updated_at`, `efectos_consecuencias`, `factores_internos`, `factores_externos`) VALUES ('202', 'R3', '25', '17', 'Analizar y revisar con suficiencia jurídica los criterios, tesis, proyectos, acuerdos y documentos sometidos a consideración o dictaminación de la Ponencia.', 'Que los criterios, tesis, proyectos, acuerdos o documentos sometidos a revisión se analicen con precedentes incompletos, inconsistencias o fuera del plazo requerido.', NULL, '2', '9', '0', '0', 'Captura', NULL, '2026-09-21 09:53:02', '2026-09-21 19:39:42', NULL, 'Volumen de documentos; recepción tardía; criterios novedosos o contradictorios; identificación incompleta de precedentes; tiempo insuficiente de revisión.', NULL);
INSERT INTO `riesgos` (`id`, `local_id`, `area_id`, `ejercicio_id`, `objetivo`, `riesgo`, `factores`, `probabilidad`, `impacto`, `probabilidad_inicial`, `impacto_inicial`, `status`, `last_observation`, `created_at`, `updated_at`, `efectos_consecuencias`, `factores_internos`, `factores_externos`) VALUES ('203', 'R4', '25', '17', 'Atender oportunamente las comisiones de Magistraturas y los asuntos administrativos sometidos al análisis de la Ponencia, generando los informes, acuerdos u observaciones correspondientes.', 'Que las comisiones, informes, acuerdos o asuntos administrativos asignados a la Ponencia no sean analizados o atendidos oportunamente.', NULL, '2', '8', '0', '0', 'Captura', NULL, '2026-09-21 09:53:02', '2026-09-21 19:39:42', NULL, 'Cargas jurisdiccionales concurrentes; información dispersa o incompleta; definición insuficiente de encargos; coordinación interáreas insuficiente.', NULL);
INSERT INTO `riesgos` (`id`, `local_id`, `area_id`, `ejercicio_id`, `objetivo`, `riesgo`, `factores`, `probabilidad`, `impacto`, `probabilidad_inicial`, `impacto_inicial`, `status`, `last_observation`, `created_at`, `updated_at`, `efectos_consecuencias`, `factores_internos`, `factores_externos`) VALUES ('204', 'R5', '25', '17', 'Preservar, en el ámbito de actuación de la Ponencia, la autonomía, independencia e imparcialidad de la función jurisdiccional.', 'Que actuaciones o decisiones de la Ponencia se desarrollen sin salvaguardas suficientes de autonomía, independencia o imparcialidad.', NULL, '1', '10', '0', '0', 'Captura', NULL, '2026-09-21 09:53:02', '2026-09-21 19:39:42', NULL, 'Presiones externas o internas; conflictos de interés; intervención indebida; falta de identificación o atención de impedimentos.', NULL);
